import hashlib

def hash_certificate_with_salt(cert: str, salt: str = "default_salt") -> str:
    """
    Hash the certificate with a salt to improve security against precomputed hash attacks.
    """
    if not cert:
        raise ValueError("Certificate content cannot be empty")
    if not salt:
        raise ValueError("Salt cannot be empty for secure hashing")
    hash_object = hashlib.sha256((cert + salt).encode('utf-8'))
    return hash_object.hexdigest()

# Example usage
print(hash_certificate_with_salt("example_certificate_data", "secure_salt"))
